use corpse_core::{startup,generation};
fn main(){for seed in ["生成-é-🌱-37"]{let mut r=startup::new_run_shell_revision(seed,"Unblessed",false,37.).unwrap();let result=startup::ensure_floors_with(&mut r,40,&|d,s,u| {let f=generation::generate_floor_full_revision(d,s,u,37.).map_err(|e|format!("depth={d} seed_hash={s} up={u:?}: {e}"))?;if let Some(e)=f.godbeast_event.as_ref(){if let Some(t)=e.tap.as_ref(){let at=t.y as usize*f.width()+t.x as usize;println!("seed={seed} depth={d} godbeast={} tap=({}, {}) tile={}",e.kind,t.x,t.y,f.tiles[at]);}}Ok(f)});println!("seed={seed} result={result:?} retained={}",r.floors.len());}}
